<?php
/** Proof — statuses and the matrix (spec "Proof", 1–3): the guard's sentences, archive refusals, the matrix deleting and restoring rows, closed terminal, same-category cells not shown. */
require __DIR__ . '/lib.php';
$owner = as_member(1);
$req = requester_of_member(26);

echo "1. The guard\n";
[$c, $b] = act($owner, '/settings/statuses/save.php', ['label' => 'SMOKE Fresh', 'category' => 'new']);
ok($c === 422 && msg($b) === 'A custom status may be open, pending, on hold or solved — never new or closed.', 'a new status in category new: 422 in the database\'s sentence');
[$c, $b] = act($owner, '/settings/statuses/save.php', ['label' => 'SMOKE Done', 'category' => 'closed']);
ok($c === 422 && str_contains(msg($b), 'never new or closed'), 'in category closed: 422');
[$c, $b] = act($owner, '/settings/statuses/save.php', ['status' => status_id('open'), 'category' => 'pending']);
ok($c === 422 && msg($b) === 'A built-in status keeps its category.', 'changing a built-in\'s category: 422 "A built-in status keeps its category."');
[$c, $b] = act($owner, '/settings/statuses/save.php', ['status' => status_id('open'), 'label' => 'SMOKE Working']);
ok($c === 200 && (string) one("SELECT label FROM ticket_statuses WHERE key = 'open'") === 'SMOKE Working' && (string) one("SELECT category FROM ticket_statuses WHERE key = 'open'") === 'open', 'renaming a built-in: allowed; its category and key stay');
act($owner, '/settings/statuses/save.php', ['status' => status_id('open'), 'label' => 'Open']);
$since = last_activity_id();
[$c, $b] = act($owner, '/settings/statuses/save.php', ['label' => 'SMOKE Waiting on vendor', 'category' => 'on_hold', 'color' => 'warning', 'sort_order' => 45]);
$sid = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $sid > 0 && q('SELECT key, clock_runs, on_board FROM ticket_statuses WHERE id = :s', ['s' => $sid])[0] == ['key' => 'smoke_waiting_on_vendor', 'clock_runs' => false, 'on_board' => true], 'a custom on-hold status: key derived, the clock pauses by default, on the board');
ok(count(activity('status.save', $since)) === 1 && str_contains((string) activity('status.save', $since)[0]['after'], '"category": "on_hold"'), 'status.save logged with the category');
[$c, $b] = act($owner, '/settings/statuses/save.php', ['label' => 'SMOKE Waiting on vendor', 'category' => 'open']);
ok($c === 200 && (string) one('SELECT key FROM ticket_statuses WHERE id = :s', ['s' => (int) $b['record_id']]) === 'smoke_waiting_on_vendor_2', 'the same label again: the key gets a number');
act($owner, '/settings/statuses/archive.php', ['status' => (int) $b['record_id']]);
[$c, $b] = act($owner, '/settings/statuses/save.php', ['label' => 'SMOKE Bad colour', 'category' => 'open', 'color' => 'pink']);
ok($c === 422 && isset(fields($b)['color']), 'a colour off the locked seven: 422');
$since = last_activity_id();
[$c, $b] = act($owner, '/settings/statuses/save.php', ['status' => $sid, 'clock_runs' => 'yes']);
ok($c === 200 && json_decode((string) activity('status.save', $since)[0]['after'], true) === ['clock_runs' => true] && (string) one('SELECT label FROM ticket_statuses WHERE id = :s', ['s' => $sid]) === 'SMOKE Waiting on vendor', 'one field changed: logged alone, the label kept');
[$c, $d] = screen($owner, '/settings/statuses/');
$keys = array_column($d['statuses'], 'key');
ok(array_search('smoke_waiting_on_vendor', $keys, true) === 4 && $d['statuses'][5]['key'] === 'solved', 'the list is in board order: the custom status sits between on_hold and solved (sort 45)');
[$c, $b] = act($owner, '/settings/statuses/save.php', ['status' => $sid, 'move' => 'down']);
[$c2, $d] = screen($owner, '/settings/statuses/');
ok($c === 200 && array_search('smoke_waiting_on_vendor', array_column($d['statuses'], 'key'), true) === 5, 'Move down: now after solved');
act($owner, '/settings/statuses/save.php', ['status' => $sid, 'move' => 'up']);

echo "2. Archive\n";
$t1 = mkticket($req, general_queue(), 'SMOKE vendor one'); $t2 = mkticket($req, general_queue(), 'SMOKE vendor two');
q('UPDATE tickets SET status_id = :s WHERE id IN (:a, :b)', ['s' => $sid, 'a' => $t1, 'b' => $t2]);
[$c, $b] = act($owner, '/settings/statuses/archive.php', ['status' => $sid]);
ok($c === 422 && msg($b) === '2 tickets are in SMOKE Waiting on vendor — move them first.', 'archiving a status holding 2 tickets: 422 naming the count');
[$c, $b] = act($owner, '/settings/statuses/archive.php', ['status' => status_id('pending')]);
ok($c === 422 && msg($b) === 'A built-in status is renamed, never archived.', 'a built-in: 422 "A built-in status is renamed, never archived."');
q('UPDATE tickets SET status_id = :s WHERE id IN (:a, :b)', ['s' => status_id('open'), 'a' => $t1, 'b' => $t2]);
$since = last_activity_id();
[$c, $b] = act($owner, '/settings/statuses/archive.php', ['status' => $sid]);
ok($c === 200 && one('SELECT archived_at FROM ticket_statuses WHERE id = :s', ['s' => $sid]) !== null && count(activity('status.archive', $since)) === 1, 'empty: archived and logged');
[$c, $d] = screen($owner, '/settings/statuses/');
ok(!in_array('smoke_waiting_on_vendor', array_column($d['statuses'], 'key'), true), 'gone from the list (the forms)');
ok((string) one('SELECT label FROM mcp_ticket_statuses WHERE status_id = :s', ['s' => $sid]) === 'SMOKE Waiting on vendor', 'still named by the view');
ok(q('SELECT * FROM hd_transition(:a, :b)', ['a' => status_id('open'), 'b' => $sid]) === [], 'and hd_transition() refuses a move into it');
ok(page($owner, '/settings/statuses/' . $sid . '/edit')['code'] === 200 && !str_contains(page($owner, '/settings/statuses/' . $sid . '/edit')['body'], 'id="status-form-archive-btn"'), 'its edit page opens without an Archive button');

echo "3. The matrix\n";
ok(count(q('SELECT * FROM hd_transition(:a, :b)', ['a' => status_id('open'), 'b' => status_id('solved')])) === 1, 'hd_transition(open, solved) answers the seeded row');
$since = last_activity_id();
[$c, $b] = act($owner, '/settings/statuses/transition.php', ['from_category' => 'open', 'to_category' => 'solved', 'allowed' => 'no']);
ok($c === 200 && one("SELECT 1 FROM status_transitions WHERE from_category = 'open' AND to_category = 'solved'") === false, 'turning open → solved off deletes the row');
ok(q('SELECT * FROM hd_transition(:a, :b)', ['a' => status_id('open'), 'b' => status_id('solved')]) === [], 'and hd_transition(open, solved) answers nothing');
$log = activity('transition.save', $since);
ok(count($log) === 1 && json_decode((string) $log[0]['after'], true)['allowed'] === false && json_decode((string) $log[0]['before'], true)['allowed'] === true, 'transition.save logged: allowed true → false');
[$c, $b] = act($owner, '/settings/statuses/transition.php', ['from_category' => 'open', 'to_category' => 'solved', 'allowed' => 'yes', 'requires' => ['resolution_code'], 'may_carry' => ['assignee'], 'needs_right' => 'tickets.work', 'label' => 'Solve']);
$row = q("SELECT requires, may_carry, needs_right, label FROM status_transitions WHERE from_category = 'open' AND to_category = 'solved'")[0] ?? null;
ok($c === 200 && $row !== null && $row['requires'] === '{resolution_code}' && $row['may_carry'] === '{assignee_member_id}' && $row['label'] === 'Solve', 'turning it back on with requires = {resolution_code}: restored (assignee stored as assignee_member_id)');
ok(count(q('SELECT * FROM hd_transition(:a, :b)', ['a' => status_id('open'), 'b' => status_id('solved')])) === 1, 'hd_transition(open, solved) answers again');
[$c, $b] = act($owner, '/settings/statuses/transition.php', ['from_category' => 'closed', 'to_category' => 'open', 'allowed' => 'yes']);
ok($c === 422 && str_contains(msg($b), 'Closed is terminal'), 'closed → anything cannot be saved: 422');
[$c, $b] = act($owner, '/settings/statuses/transition.php', ['from_category' => 'open', 'to_category' => 'open', 'allowed' => 'yes']);
ok($c === 422 && str_contains(msg($b), 'always allowed'), 'a cell in the same category: 422 (always allowed)');
[$c, $b] = act($owner, '/settings/statuses/transition.php', ['from_category' => 'open', 'to_category' => 'pending', 'requires' => ['assignee']]);
ok($c === 422 && isset(fields($b)['requires']), 'requires outside the two: 422');
[$c, $b] = act($owner, '/settings/statuses/transition.php', ['from_category' => 'open', 'to_category' => 'pending', 'needs_right' => 'settings.manage']);
ok($c === 422 && isset(fields($b)['needs_right']), 'a right outside the two: 422');
[$c, $b] = act($owner, '/settings/statuses/transition.php', ['from_category' => 'pending', 'to_category' => 'closed', 'allowed' => 'yes', 'needs_right' => 'tickets.manage', 'label' => 'SMOKE Close now']);
ok($c === 200 && (string) one("SELECT label FROM status_transitions WHERE from_category = 'pending' AND to_category = 'closed'") === 'SMOKE Close now', 'a new move (pending → closed) is added');
$body = page($owner, '/settings/statuses/transitions')['body'];
ok(str_contains($body, 'id="transition-open-open-same"') && str_contains($body, 'id="transition-closed-open-never"') && str_contains($body, 'id="transition-open-solved-form"') && str_contains($body, 'id="transitions-words-pending-closed"'), 'the grid: the diagonal struck, the closed row never, a form per cell, the words below');
[$c, $d] = screen($owner, '/settings/statuses/transitions');
ok(count($d['transitions']) === 17 && array_values(array_filter($d['transitions'], fn ($t) => $t['from_category'] === 'open' && $t['to_category'] === 'solved'))[0]['words'] === 'Solve — needs a resolution code; may carry an assignee; support staff', 'JSON: 17 moves, each in words');
act($owner, '/settings/statuses/transition.php', ['from_category' => 'pending', 'to_category' => 'closed', 'allowed' => 'no']);
finish();
